mapper.select:
SELECT COUNT(*) FROM ${table}
WHERE user_id = #{userId}
 AND ${pk} = #{alertId} 
 AND status = #{status}

SELECT ${pk} AS id, user_id, `type`, title, body, payload, status,
       created_at, delivered_at, seen_at
FROM ${table}
WHERE user_id = #{userId}
 AND ${pk} = #{alertId} 
 AND status = #{status} 
ORDER BY created_at DESC, ${pk} DESC
LIMIT #{limit} OFFSET #{offset}

SELECT ${pk} AS id, user_id, status, delivered_at, seen_at
FROM ${table}
WHERE ${pk} = #{id}
  AND user_id = #{userId}
LIMIT 1

mapper.update:
UPDATE ${table}
SET status = 'SENT',
    delivered_at = COALESCE(delivered_at, #{now})
WHERE ${pk} = #{id}
  AND user_id = #{userId}
  AND status = 'PENDING'

UPDATE ${table}
SET status = 'SEEN',
    seen_at = CASE WHEN seen_at IS NULL THEN #{now} ELSE seen_at END
WHERE ${pk} = #{id}
  AND user_id = #{userId}

UPDATE ${table}
SET status = 'SEEN',
    seen_at = COALESCE(seen_at, #{now})
WHERE user_id = #{userId}
  AND status IN ('PENDING','SENT')

